// pixi-no-eval - Writes worker/pixi-no-eval.js: PixiJS's own "pixi.js/unsafe-eval" add-on (shader and uniform code without new Function)
// as one file that patches the dist/pixi.mjs bundle the page loads (the add-on's own files patch lib/ copies the page never uses).
// Lets the page's CSP drop 'unsafe-eval'. Run after a PixiJS update; tests/static/pixi-no-eval.test.mjs fails when it's stale.
//   node tools/pixi-no-eval.mjs
import { readFileSync, writeFileSync, readdirSync } from "node:fs";
import { dirname, join, resolve, relative } from "node:path";
import { fileURLToPath } from "node:url";

const web = join(dirname(fileURLToPath(import.meta.url)), "..");
const lib = join(web, "node_modules/pixi.js/lib/unsafe-eval");
export function pixiNoEval() {
	const files = [], walk = (d) => { for (const e of readdirSync(d, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) if (e.isDirectory()) walk(join(d, e.name)); else if (e.name.endsWith(".mjs")) files.push(join(d, e.name)); };
	walk(lib);
	files.sort((a, b) => (a.endsWith("/init.mjs") ? 1 : 0) - (b.endsWith("/init.mjs") ? 1 : 0)); // init runs selfInstall(): last
	const fromPixi = new Set(), bodies = [];
	for (const f of files) {
		let t = readFileSync(f, "utf8");
		t = t.replace(/^import \{([^}]*)\} from '([^']+)';\n/gm, (_, names, p) => {
			if (!resolve(dirname(f), p).startsWith(lib + "/")) for (const n of names.split(",")) fromPixi.add(n.trim());
			return "";
		});
		t = t.replace(/^"use strict";\n/m, "").replace(/^\/\/# sourceMappingURL=.*\n?/m, "").replace(/^export \{[^}]*\};\n/gm, "");
		bodies.push(`// ---- ${relative(join(web, "node_modules"), f)}\n${t.trim()}\n`);
	}
	const version = JSON.parse(readFileSync(join(web, "node_modules/pixi.js/package.json"), "utf8")).version;
	return `// GENERATED by tools/pixi-no-eval.mjs from pixi.js ${version} lib/unsafe-eval (MIT, PixiJS). Don't edit: re-run the tool.\n`
		+ `import { ${[...fromPixi].sort().join(", ")} } from "pixi.js";\n\n${bodies.join("\n")}`;
}
if (process.argv[1] === fileURLToPath(import.meta.url)) { writeFileSync(join(web, "worker/pixi-no-eval.js"), pixiNoEval()); console.log("wrote worker/pixi-no-eval.js"); }
